const REVISION = '160';

const MOUSE = { LEFT: 0, MIDDLE: 1, RIGHT: 2, ROTATE: 0, DOLLY: 1, PAN: 2 };
const

input.content:
:root {
  --red: #e41e3f;
  --red-dark: #a90d27;
  --blue: #2456d8;
  --blue-dark: #142e86;
  --cream: #f7f0e2;
  --ink: #0a0912;
  --gold: #ffcf5c;
  --panel: rgba(11, 9, 22, 0.74);
  --line: rgba(247, 240, 226, 0.16);
  --font-display: "Arial Black", "Arial Bold", "Helvetica Neue", Impact, sans-serif;
  --font-body: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #08060f;
  color: var(--cream);
  font-family: var(--font-body);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { user-select: none; -webkit-user-select: none; }

#app { position: relative; width: 100%; height: 100%; overflow: hidden; }

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.screen-fx { position: absolute; inset: 0; pointer-events: none; }

#vignette {
  background:
    radial-gradient(ellipse at 50% 48%, transparent 46%, rgba(5, 3, 12, 0.42) 100%),
    linear-gradient(to bottom, rgba(5, 3, 12, 0.25), transparent 22%, transparent 76%, rgba(5, 3, 12, 0.4));
}

#flash {
  background: radial-gradient(circle at 50% 60%, rgba(255, 210, 150, 0.9), transparent 62%);
  opacity: 0;
  transition: opacity 0.45s ease-out;
}

#speedlines {
  opacity: 0;
  mix-blend-mode: screen;
  background:
    repeating-conic-gradient(from 0deg at 50% 50%, rgba(255,255,255,0.16) 0deg 0.35deg, transparent 0.35deg 6deg);
  mask-image: radial-gradient(circle at 50% 50%, transparent 0%, transparent 38%, #000 78%);
  -webkit-mask-image: radial-gradient(circle at 50% 50%, transparent 0%, transparent 38%, #000 78%);
  transition: opacity 0.25s linear;
}

/* ===================== HUD ===================== */
.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.4s ease;
}
.hud.visible { opacity: 1; }

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.34);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.eyebrow {
  display: block;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ff7a8f;
}

.objective {
  position: absolute;
  top: calc(18px + var(--safe-t));
  left: calc(18px + var(--safe-l));
  padding: 13px 19px 12px 18px;
  min-width: 244px;
  border-left: 3px solid var(--red);
  transform: skewX(-4deg);
  animation: hud-in 0.6s cubic-bezier(.2,.8,.2,1) both;
}
.objective > * { transform: skewX(4deg); }
.obj-title {
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}
.obj-progress {
  margin-top: 5px;
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--font-display);
  line-height: 1;
}
.obj-progress strong { font-size: 30px; color: var(--gold); text-shadow: 0 2px 0 rgba(0,0,0,.5); }
.obj-progress .slash, .obj-progress span:last-child { font-size: 14px; color: rgba(247,240,226,.55); }

.timer-wrap {
  position: absolute;
  top: calc(16px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  animation: hud-in 0.6s 0.05s cubic-bezier(.2,.8,.2,1) both;
}
.timer {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.4vw, 38px);
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 3px 0 rgba(0,0,0,.45), 0 0 26px rgba(255, 100, 80, 0.28);
}
.best {
  margin-top: 1px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: rgba(247, 240, 226, 0.5);
}

.minimap-wrap {
  position: absolute;
  top: calc(18px + var(--safe-t));
  right: calc(18px + var(--safe-r));
  width: 164px;
  height: 164px;
  border-radius: 50%;
  padding: 9px;
  animation: hud-in 0.6s 0.1s cubic-bezier(.2,.8,.2,1) both;
}
#minimap { width: 100%; height: 100%; display: block; border-radius: 50%; }
.minimap-n {
  position: absolute;
  top: -3px; left: 50%;
  transform: translateX(-50%);
  width: 20px; height: 20px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: var(--red);
  color: #fff;
  font-size: 9px;
  font-weight: 900;
  box-shadow: 0 2px 8px rgba(0,0,0,.5);
}

.speed-wrap {
  position: absolute;
  left: calc(22px + var(--safe-l));
  bottom: calc(24px + var(--safe-b));
  width: 188px;
  animation: hud-in 0.6s 0.15s cubic-bezier(.2,.8,.2,1) both;
}
.speed-readout {
  display: flex;
  align-items: baseline;
  gap: 7px;
  font-family: var(--font-display);
  font-style: italic;
}
.speed-readout span {
  font-size: 42px;
  line-height: 0.9;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 0 rgba(0,0,0,.45);
}
.speed-readout small { font-size: 10px; letter-spacing: 0.2em; color: rgba(247,240,226,.55); }
.speed-bar {
  margin-top: 7px;
  height: 5px;
  background: rgba(255,255,255,.14);
  border-radius: 3px;
  overflow: hidden;
  transform: skewX(-20deg);
}
.speed-bar i {
  display: block;
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #46e0ff, var(--gold) 60%, var(--red));
  border-radius: 3px;
  box-shadow: 0 0 12px rgba(255, 180, 100, .6);
  transition: width 0.08s linear;
}
.state-label {
  margin-top: 6px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: rgba(247, 240, 226, 0.46);
}

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(28px + var(--safe-b));
  transform: translateX(-50%);
  padding: 9px 17px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: rgba(247, 240, 226, 0.72);
  background: rgba(9, 7, 18, 0.55);
  border: 1px solid var(--line);
  border-radius: 999px;
  white-space: nowrap;
  transition: opacity 0.8s ease;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.hint.fade { opacity: 0; }
kbd {
  display: inline-block;
  min-width: 20px;
  padding: 2px 5px;
  border: 1px solid rgba(247,240,226,.4);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: rgba(255,255,255,.08);
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-align: center;
  color: var(--cream);
}

.reticle {
  position: absolute;
  top: 50%; left: 50%;
  width: 26px; height: 26px;
  transform: translate(-50%, -50%);
  opacity: 0.35;
  transition: opacity .2s, transform .2s;
}
.reticle i, .reticle b {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(255,255,255,.55);
  border-radius: 50%;
}
.reticle i::before, .reticle i::after {
  content: "";
  position: absolute;
  background: rgba(255,255,255,.7);
}
.reticle i::before { width: 1px; height: 7px; left: 50%; top: -4px; }
.reticle i::after { width: 1px; height: 7px; left: 50%; bottom: -4px; }
.reticle b {
  inset: 11px;
  border: 0;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 0 8px rgba(255,255,255,.8);
}
.reticle.ready { opacity: 1; transform: translate(-50%, -50%) scale(1.12); }
.reticle.ready i { border-color: var(--gold); box-shadow: 0 0 14px rgba(255,207,92,.5); }
.reticle.ready b { background: var(--gold); box-shadow: 0 0 10px rgba(255,207,92,.9); }
.reticle.hidden { opacity: 0; }

.toast {
  position: absolute;
  left: 50%;
  top: 27%;
  transform: translate(-50%, 12px);
  padding: 11px 24px;
  font-family: var(--font-display);
  font-size: 15px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink);
  background: var(--gold);
  border: 2px solid var(--ink);
  box-shadow: 6px 6px 0 rgba(0,0,0,.35);
  opacity: 0;
  transition: opacity .25s, transform .25s;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0) rotate(-1.5deg); }
.toast.bad { background: var(--red); color: #fff; }

.mission-complete {
  position: absolute;
  left: 50%; top: 50%;
  transform: translate(-50%, -50%) scale(.92);
  width: min(440px, calc(100vw - 40px));
  padding: 34px 30px 30px;
  text-align: center;
  background: linear-gradient(160deg, rgba(16, 12, 30, .96), rgba(30, 10, 25, .96));
  border: 2px solid var(--gold);
  box-shadow: 0 30px 90px rgba(0,0,0,.7), inset 0 0 60px rgba(255,207,92,.08);
  opacity: 0;
  pointer-events: none;
  transition: opacity .45s, transform .45s cubic-bezier(.2,.9,.3,1.2);
}
.mission-complete.show { opacity: 1; pointer-events: auto; transform: translate(-50%, -50%) scale(1); }
.mission-complete h2 {
  margin: 6px 0 2px;
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(36px, 7vw, 58px);
  line-height: 1;
  color: var(--cream);
  text-shadow: 3px 3px 0 var(--red), -1px -1px 0 var(--blue);
}
.final-time {
  font-family: var(--font-display);
  font-size: 34px;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
  margin: 8px 0 2px;
}
.final-best { font-size: 9px; font-weight: 800; letter-spacing: .24em; color: rgba(247,240,226,.55); }
.mission-complete .btn { margin-top: 20px; }

/* ===================== BUTTONS ===================== */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 13px 26px;
  border: 2px solid var(--ink);
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  cursor: pointer;
  transform: skewX(-5deg);
  box-shadow: 5px 5px 0 rgba(0,0,0,.45);
  transition: transform .12s ease, box-shadow .12s ease, background .15s;
  outline: none;
}
.btn > * { transform: skewX(5deg); }
.btn:hover { transform: skewX(-5deg) translate(-2px, -2px); box-shadow: 8px 8px 0 rgba(0,0,0,.42); }
.btn:active { transform: skewX(-5deg) translate(2px, 2px); box-shadow: 2px 2px 0 rgba(0,0,0,.4); }
.btn-primary {
  background: linear-gradient(180deg, #ff2c50, #c30f2d);
  color: #fff;
  border-color: #fff;
  text-shadow: 0 2px 0 rgba(0,0,0,.25);
}
.btn-primary:hover { background: linear-gradient(180deg, #ff4765, #d31232); }
.btn-primary span {
  display: inline-grid;
  place-items: center;
  width: 18px; height: 18px;
  border: 1px solid rgba(255,255,255,.5);
  border-radius: 3px;
  font-size: 9px;
}
.btn-ghost { background: transparent; color: var(--cream); border-color: rgba(247,240,226,.3); box-shadow: none; }
.btn-ghost:hover { border-color: var(--cream); box-shadow: none; }
.btn.big { padding: 17px 42px; font-size: 16px; letter-spacing: 0.14em; }

/* ===================== COVER ===================== */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
}
.overlay.open { display: block; }
.overlay.hidden { display: none; }

.cover {
  background:
    radial-gradient(ellipse at 74% 42%, transparent 0%, rgba(8, 5, 18, 0.35) 46%, rgba(8, 5, 18, 0.92) 100%),
    linear-gradient(100deg, rgba(8, 5, 18, 0.94) 0%, rgba(8, 5, 18, 0.72) 35%, rgba(8, 5, 18, 0.05) 68%),
    repeating-linear-gradient(115deg, rgba(255,255,255,0.02) 0 2px, transparent 2px 7px);
}
.cover-art { position: absolute; inset: 0; overflow: hidden; }
.cover-inner {
  position: relative;
  z-index: 2;
  width: min(640px, 92vw);
  padding: max(34px, 5vh) 0 0 max(28px, 7vw);
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
}
.kicker {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.34em;
  color: var(--gold);
  margin-bottom: 10px;
  animation: rise .7s .05s both;
}
.logo {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(54px, 9.2vw, 108px);
  line-height: 0.82;
  letter-spacing: -0.045em;
  color: var(--cream);
  text-shadow:
    5px 5px 0 var(--red),
    10px 10px 0 rgba(36, 86, 216, 0.9),
    16px 16px 34px rgba(0,0,0,.55);
  transform: skewX(-4deg);
  animation: rise .7s .12s both;
}
.logo-blue { color: #9fb9ff; }
.logo-dash { color: var(--red); }
.subtitle {
  align-self: flex-start;
  margin: 10px 0 0 4px;
  padding: 5px 20px 6px;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(17px, 2.4vw, 26px);
  letter-spacing: 0.34em;
  transform: skewX(-8deg) rotate(-1.2deg);
  box-shadow: 4px 4px 0 var(--blue);
  animation: rise .7s .2s both;
}
.blurb {
  max-width: 430px;
  margin: 22px 0 24px;
  font-size: 13.5px;
  line-height: 1.65;
  color: rgba(247, 240, 226, 0.72);
  animation: rise .7s .28s both;
}
#playBtn { animation: rise .7s .36s both; }
.controls-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px 18px;
  width: 100%;
  max-width: 530px;
  margin-top: 30px;
  animation: rise .7s .45s both;
}
.controls-grid > div { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
.controls-grid span { font-size: 9.5px; letter-spacing: 0.04em; color: rgba(247,240,226,.55); margin-left: 3px; }
.touch-copy { display: none; }
.tick { color: var(--gold); font-size: 15px; }
.fineprint { margin-top: 22px; font-size: 9px; letter-spacing: 0.08em; color: rgba(247,240,226,.28); }
.cover-vignette {
  position: absolute; inset: 0;
  background: radial-gradient(circle at 74% 45%, transparent 30%, rgba(5,3,12,.55) 100%);
  pointer-events: none;
}
.web-corner {
  position: absolute;
  width: 380px; height: 380px;
  opacity: .14;
  pointer-events: none;
  background:
    repeating-conic-gradient(from 200deg at 0 0, rgba(255,255,255,.5) 0deg .18deg, transparent .18deg 18deg),
    repeating-radial-gradient(circle at 0 0, transparent 0 33px, rgba(255,255,255,.5) 33px 34px);
  mask-image: radial-gradient(circle at 0 0, #000 0 70%, transparent 71%);
  -webkit-mask-image: radial-gradient(circle at 0 0, #000 0 70%, transparent 71%);
}
.web-corner.tl { top: -60px; left: -60px; transform: rotate(90deg); }
.web-corner.tr { top: -60px; right: -60px; transform: rotate(180deg); }

@keyframes rise {
  from { opacity: 0; transform: translateY(22px) skewX(-4deg); }
  to { opacity: 1; transform: translateY(0) skewX(-4deg); }
}
@keyframes hud-in {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Loading */
.loading {
  display: grid;
  place-items: center;
  background: #08060f;
  z-index: 40;
}
.loading.hidden { display: none; }
.loading-title {
  position: absolute;
  bottom: 22%;
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: .3em;
  color: rgba(247,240,226,.65);
}
.loading-bar {
  position: absolute;
  bottom: 18%;
  width: 220px; height: 2px;
  background: rgba(255,255,255,.12);
  overflow: hidden;
}
.loading-bar i { display: block; height: 100%; width: 0%; background: var(--red); transition: width .3s ease; }
.loader-web {
  width: 54px; height: 54px;
  border: 2px solid rgba(255,255,255,.15);
  border-top-color: var(--red);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* Pause */
.pause {
  background: rgba(6, 4, 14, 0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 35;
}
.pause.open { display: grid; place-items: center; }
.pause-card {
  width: min(380px, calc(100vw - 36px));
  padding: 28px;
  text-align: center;
  border-top: 3px solid var(--red);
}
.pause-card h2 {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 44px;
  margin: 4px 0 18px;
  text-shadow: 3px 3px 0 var(--red);
}
.pause-stats { display: flex; justify-content: center; gap: 30px; margin-bottom: 22px; }
.pause-stats div { display: flex; flex-direction: column; gap: 3px; }
.pause-stats span { font-size: 9px; letter-spacing: .2em; color: rgba(247,240,226,.45); }
.pause-stats strong { font-family: var(--font-display); font-size: 18px; color: var(--gold); }
.pause-card .btn { display: flex; width: 100%; margin-top: 10px; }
.pause-help { display: flex; justify-content: center; gap: 22px; margin-top: 18px; font-size: 9px; color: rgba(247,240,226,.4); }

/* Sound + pause buttons */
.sound-toggle, .pause-toggle {
  position: fixed;
  z-index: 45;
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(9, 7, 18, 0.62);
  color: rgba(247,240,226,.7);
  font-size: 14px;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: color .15s, border-color .15s, opacity .2s;
  opacity: 0;
  pointer-events: none;
}
.sound-toggle { right: calc(18px + var(--safe-r)); bottom: calc(20px + var(--safe-b)); }
.pause-toggle { right: calc(62px + var(--safe-r)); bottom: calc(20px + var(--safe-b)); font-size: 9px; }
.playing .sound-toggle, .playing .pause-toggle { opacity: 1; pointer-events: auto; }
.sound-toggle:hover, .pause-toggle:hover { color: #fff; border-color: rgba(255,255,255,.5); }
.sound-toggle.muted { color: var(--red); text-decoration: line-through; }

/* ===================== TOUCH ===================== */
.touch-ui { position: absolute; inset: 0; pointer-events: none; display: none; z-index: 20; }
body.touch .touch-ui { display: block; }
body.touch .hint { display: none; }
body.touch .controls-grid { grid-template-columns: 1fr 1fr; }
body.touch #desktopControls { display: none; }
body.touch .touch-copy { display: grid; }
body.touch .sound-toggle { bottom: calc(18px + var(--safe-b)); right: auto; left: 50%; transform: translateX(-50%); }
body.touch .pause-toggle { bottom: calc(18px + var(--safe-b)); right: calc(18px + var(--safe-r)); }

.joystick {
  position: absolute;
  left: calc(22px + var(--safe-l));
  bottom: calc(26px + var(--safe-b));
  width: 124px; height: 124px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.22);
  background: radial-gradient(circle, rgba(255,255,255,.08), rgba(10,8,20,.24));
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.joystick::before {
  content: "";
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 1px dashed rgba(255,255,255,.12);
}
.stick {
  position: absolute;
  left: 50%; top: 50%;
  width: 52px; height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, #ff5572, #b60e2a);
  border: 2px solid rgba(255,255,255,.55);
  box-shadow: 0 4px 18px rgba(0,0,0,.45);
  transition: transform .05s linear;
}
.touch-buttons {
  position: absolute;
  right: calc(18px + var(--safe-r));
  bottom: calc(24px + var(--safe-b));
  width: 176px; height: 158px;
  pointer-events: none;
}
.tbtn {
  position: absolute;
  pointer-events: auto;
  touch-action: none;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.4);
  background: rgba(12, 9, 24, 0.5);
  color: #fff;
  font-family: var(--font-display);
  letter-spacing: .06em;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow: 0 6px 18px rgba(0,0,0,.35);
  transition: transform .08s, background .08s;
}
.tbtn:active, .tbtn.down { transform: scale(.93); background: rgba(255,255,255,.18); }
.tbtn-web {
