    new THREE.Vector3(x + w / 2, h + 0.42, z + d / 2)
  ));

  // roof parapet
  const parapet = new THREE.Mesh(new THREE.BoxGeometry(w + 0.5, 0.7, d + 0.5), trimMat);
  parapet.position.set(x, h + 0.5, z);
  group.add(parapet);

  // setback tower
  if (h > 48 && rand() < 0.62) {
    const w2 = w * (0.5 + rand() * 0.22);
    const d2 = d * (0.5 + rand() * 0.22);
    const h2 = 10 + rand() * 30;
    const geo2 = makeBuildingGeometry(w2, h2, d2);
    const m2 = new THREE.Mesh(geo2, [mat, mat, roofMat, roofMat, mat, mat]);
    m2.position.set(x + (rand() - 0.5) * (w - w2) * 0.6, h + 0.85 + h2 / 2, z + (rand() - 0.5) * (d - d2) * 0.6);
    m2.castShadow = true;
    m2.receiveShadow = true;
    group.add(m2);
    buildingMeshes.push(m2);
    colliders.push(new THREE.Box3(
      new THREE.Vector3(m2.position.x - w2 / 2, h + 0.42, m2.position.z - d2 / 2),
